```json
{
  "schemaVersion": "0.3.0-alpha",
  "programId": "western-blot-sds-page-wet-transfer-overnight",
  "name": "Western Blot: SDS-PAGE, Wet Transfer and Overnight Primary",
  "description": "One 10-lane gel, wet transfer to PVDF, overnight primary antibody in cold room. Includes sample prep, gel run, transfer, blocking, primary/secondary probing, and detection.",
  "environmentType": "laboratory",
  "actors": 1,
  "tracks": [
    {
      "trackId": "sample_and_gel",
      "name": "Sample Prep & Gel Run",
      "steps": [
        {
          "stepId": "thaw_normalise",
          "name": "Thaw lysates on ice and normalise to 2 mg/mL",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "programStart" }
        },
        {
          "stepId": "denature",
          "name": "Add Laemmli buffer and denature at 95 °C",
          "task": "heat_block",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "thaw_normalise" }
        },
        {
          "stepId": "spin_condensate",
          "name": "Spin tubes to collect condensate",
          "task": "microcentrifuge",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "denature" }
        },
        {
          "stepId": "assemble_tank",
          "name": "Assemble gel tank, seat gel, fill with running buffer",
          "task": "gel_tank",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "spin_condensate" }
        },
        {
          "stepId": "load_gel",
          "name": "Load 20 µg per lane and 5 µL protein ladder",
          "task": "gel_tank",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "assemble_tank" }
        },
        {
          "stepId": "run_gel",
          "name": "Run at 120 V for 75 minutes",
          "task": "gel_tank",
          "duration": { "type": "fixed", "seconds": 4500 },
          "startTrigger": { "type": "afterStep", "stepId": "load_gel" }
        }
      ]
    },
    {
      "trackId": "transfer_prep",
      "name": "Transfer Buffer & Membrane Prep",
      "steps": [
        {
          "stepId": "chill_buffer",
          "name": "Put 1 L transfer buffer in cold room",
          "task": "cold_room",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "programStart" }
        },
        {
          "stepId": "prep_membrane",
          "name": "Wet PVDF in methanol and equilibrate in transfer buffer",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "programStartOffset", "offsetSeconds": 3600 }
        },
        {
          "stepId": "soak_pads_paper",
          "name": "Soak fibre pads and filter paper in cold transfer buffer",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "prep_membrane" }
        }
      ]
    },
    {
      "trackId": "blot_and_detection",
      "name": "Blot, Probing & Detection",
      "steps": [
        {
          "stepId": "wait_gel_finish",
          "name": "Wait for gel run to finish",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "run_gel", "offsetSeconds": 300 }
        },
        {
          "stepId": "build_sandwich",
          "name": "Prise out gel and build transfer sandwich",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "wait_gel_finish" }
        },
        {
          "stepId": "transfer",
          "name": "Transfer at 100 V for 60 minutes",
          "task": "transfer_tank",
          "duration": { "type": "fixed", "seconds": 3600 },
          "startTrigger": { "type": "afterStep", "stepId": "build_sandwich" }
        },
        {
          "stepId": "ponceau_stain",
          "name": "Stain with Ponceau S, photograph, rinse",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "transfer" }
        },
        {
          "stepId": "block",
          "name": "Block in 5% milk on rocker for 1 hour",
          "task": "rocker",
          "duration": { "type": "fixed", "seconds": 3600 },
          "startTrigger": { "type": "afterStep", "stepId": "ponceau_stain" }
        },
        {
          "stepId": "primary_antibody",
          "name": "Probe with primary antibody overnight in cold room",
          "task": "cold_room",
          "duration": { "type": "indefinite", "defaultSeconds": 54000 },
          "startTrigger": { "type": "afterStep", "stepId": "block" }
        },
        {
          "stepId": "wash_after_primary_1",
          "name": "Wash 1 of 3 after primary (10 min on rocker)",
          "task": "rocker",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "primary_antibody" }
        },
        {
          "stepId": "wash_after_primary_2",
          "name": "Wash 2 of 3 after primary (10 min on rocker)",
          "task": "rocker",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "wash_after_primary_1" }
        },
        {
          "stepId": "wash_after_primary_3",
          "name": "Wash 3 of 3 after primary (10 min on rocker)",
          "task": "rocker",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "wash_after_primary_2" }
        },
        {
          "stepId": "secondary_antibody",
          "name": "Probe with HRP-conjugated secondary on rocker for 1 hour",
          "task": "rocker",
          "duration": { "type": "fixed", "seconds": 3600 },
          "startTrigger": { "type": "afterStep", "stepId": "wash_after_primary_3" }
        },
        {
          "stepId": "wash_after_secondary_1",
          "name": "Wash 1 of 3 after secondary (10 min on rocker)",
          "task": "rocker",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "secondary_antibody" }
        },
        {
          "stepId": "wash_after_secondary_2",
          "name": "Wash 2 of 3 after secondary (10 min on rocker)",
          "task": "rocker",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "wash_after_secondary_1" }
        },
        {
          "stepId": "wash_after_secondary_3",
          "name": "Wash 3 of 3 after secondary (10 min on rocker)",
          "task": "rocker",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "wash_after_secondary_2" }
        },
        {
          "stepId": "drain_and_substrate",
          "name": "Drain membrane and apply ECL substrate, let work 5 min",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "wash_after_secondary_3" }
        },
        {
          "stepId": "image_blot",
          "name": "Image the blot",
          "task": "imager",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "drain_and_substrate" }
        },
        {
          "stepId": "quantify",
          "name": "Quantify bands against loading control",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "afterStep", "stepId": "image_blot" }
        }
      ]
    },
    {
      "trackId": "ecl_prep",
      "name": "ECL Substrate Prep (parallel to secondary)",
      "steps": [
        {
          "stepId": "mix_ecl",
          "name": "Mix ECL substrate",
          "task": "bench",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "secondary_antibody", "offsetSeconds": -3000 }
        }
      ]
    }
  ],
  "resourceConstraints": [
    { "task": "bench", "maxConcurrent": 1 },
    { "task": "heat_block", "maxConcurrent": 1 },
    { "task": "microcentrifuge", "maxConcurrent": 1 },
    { "task": "gel_tank", "maxConcurrent": 1 },
    { "task": "transfer_tank", "maxConcurrent": 1 },
    { "task": "rocker", "maxConcurrent": 1 },
    { "task": "cold_room", "maxConcurrent": 1 },
    { "task": "imager", "maxConcurrent": 1 }
  ],
  "metadata": {
    "sourceUrl": "",
    "attribution": "Western Blot protocol: SDS-PAGE, wet transfer, overnight primary",
    "sampleCount": 10,
    "gelType": "precast",
    "voltage": "120 V (gel run), 100 V (transfer)",
    "primaryIncubation": "overnight in cold room (12–18 h)",
    "secondaryConjugate": "HRP"
  }
}
```

**Changes made:**

1. **primary_antibody**: Changed `duration.type` from `"fixed"` to `"indefinite"` with `defaultSeconds: 54000`. This allows the negative offset on `mix_ecl` to work (50 min = 3000 sec before the end of the indefinite secondary incubation).

2. **Transfer Prep track**: Fixed the overlap by making `prep_membrane` start at `programStartOffset: 3600` (1 hour into the gel run) instead of chaining off a "wait" step. Removed the separate `wait_before_membrane_prep` step. Now `chill_buffer` starts at t=0 and finishes at t=300, and `prep_membrane` starts at t=3600, with no overlap.
